parameters.jsCode:
const items = $input.all();
const out = [];

for (const item of items) {
  let raw = item.json.output;

  raw = raw.trim();
  if (raw.startsWith('```json')) {
    raw = raw.substring(7);
  } else if (raw.startsWith('```')) {
    raw = raw.substring(3);
  }

  if (raw.endsWith('```')) {
    raw = raw.substring(0, raw.length - 3);
  }
  raw = raw.trim();

  const parsed = JSON.parse(raw);

  out.push({
    json: {
      Title: parsed.Title,
      Content: parsed.Content,
      Image_keyword: parsed.Image_keyword,
    }
  });
}

return out;

parameters.text:
=Create a {{ $json['Content Type'] }} about: {{ $json['Topic or Keyword'] }} 
Tone: {{ $json.Tone }}
Length: {{ $json['Content Length'] }} words
Remember to respond with valid JSON only.

parameters.jsCode:
// Loop through all the items from the previous node
const cleanList = items.map(item => {
  // Get the title (safely handle if it's missing)
  const title = item.json.title ? item.json.title.rendered : "No Title";

  // Get the direct image link (guid.rendered is the file URL in your screenshot)
  const url = item.json.guid ? item.json.guid.rendered : "No URL";

  // Get the ID (we need this to reference it later)
  const id = item.json.id;

  // Format it as a single line of text
  return `ID: ${id} | Title: "${title}" | URL: ${url}`;
});

// Combine all lines into one big text block for the AI
return [
  {
    json: {
      image_list_for_ai: cleanList.join("\n")
    }
  }
];

